#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int parent[100001], rnk[100001];
int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }
bool unite(int a, int b) {
    a=find(a); b=find(b);
    if(a==b) return false;
    if(rnk[a]<rnk[b]) swap(a,b);
    parent[b]=a; if(rnk[a]==rnk[b]) rnk[a]++;
    return true;
}
int main() {
    int n,e; cin >> n >> e;
    vector<tuple<int,int,int>> edges;
    for(int i=0; i<e; i++) { int u,v,w; cin>>u>>v>>w; edges.push_back({w,u,v}); }
    sort(edges.begin(), edges.end());
    for(int i=0; i<n; i++) { parent[i]=i; rnk[i]=0; }
    // Kruskal's
    return 0;
}

